    [25] = {n="Paso del Espolón bloqueado", d="Envía 12 elementales de agua podrida al Lago Mystral que esperan al este de El Paso del Espolón y al suroeste del Puesto del Hachazo.\nExplora la glorieta que está en el Lago Mystral y que domina la cercana avanzada de la Alianza.\nVuelve junto a Mastok Sibilante en el Puesto del Hachazo, Vallefresno.", tgo={{"Elemental de agua podrida"}}},
    [27] = {n="Una lección que aprender", d="Ve a Claro de la Luna, al poblado Amparo de la Noche y habla con Dendrite Rafagaestelar."},
    [28] = {n="La prueba del lago", d="Lleva un adorno de altar del Lago Elune'ara al Santuario de Remulos, al noroeste de Claro de la Luna. Usa el adorno en el santuario.\nDespués, habla con Tajarri en el santuario para completar la prueba.", objs={"Santuario de Remulos"}},
    [30] = {n="La prueba del león marino", d="Busca el colgante de Agilidad acuática y el colgante de Resistencia acuática. Habla con la gente de Claro de la Luna para conseguir pistas sobre la ubicación de los colgantes.\nForma el colgante del león marino con los otros dos cuando estés cerca del Santuario de Remulos.\nLleva el colgante completo a Dendrite Rafagaestelar a Amparo de la Noche, en Claro de la Luna.", objs={"Santuario de Remulos"}},
    [31] = {n="Forma acuática", d="Vuelve a Cima del Trueno y enséñale el colgante del león marino a Turak Tótem Rúnico."},
