    [3123] = {n="Probar la vasija", d="Viaja a las Tierras del Interior y localiza a los lechúcicos. Mata a 10 de ellos y utiliza la vasija de muisek para reducir y capturar a los lechúcicos caídos.\nLleva 10 muiseks de lechúcico y la vasija de muisek al médico brujo Uzer'i a Feralas.", tgo={{"Lechubestia sañosa", "Lechubestia primitiva", "Lechubestia salvaje"}}},
    [3124] = {n="Hipogrifos muisek", d="ACaba con 10 hipogrifos Plumavieja de cualquier tipo y utiliza la vasija de muisek para encogerlos y capturarlos.", tgo={{"Hipogrifo Plumavieja", "Alacervo Plumavieja", "Tormento Rozapluma", "Patriarca Rozapluma"}}},
    [3125] = {n="Dragones feéricos muisek", d="Mata a 8 duendes dardo o duendes dragón. Utiliza la vasija de muisek para reducir y capturar a los dragones feéricos caídos.", tgo={{"Duende dragón", "Duende dardo"}}},
    [3126] = {n="Antárboles muisek", d="Mata a 3 Caminabosques deambulantes. Utiliza la vasija de muisek para reducir y capturar a los Antárboles caídos.", tgo={{"Caminabosques deambulante"}}},
    [3127] = {n="Gigantes de montaña muisek", d="Mata a 7 caminantes de la tierra o gigantes del risco. Utiliza la vasija de muisek para reducir y capturar a los gigantes de montaña caídos.", tgo={{"Caminante de la tierra", "Gigante del risco", "Caminatierras machacado", "Gigante del Acantilado machacado"}}},
    [3128] = {n="Materiales naturales", d="Lleva 2 troncos astillados, 6 minerales taraceados, 20 tendones elásticos y 40 fragmentos metálicos al médico brujo Uzer'i al Campamento Mojache.", tgo={{"Caminabosques deambulante"}, {"Duende dragón", "Duende dardo", "Caminante de la tierra", "Gigante del risco", "Duende lanzadardos capturado", "Caminatierras machacado", "Gigante del Acantilado machacado"}, {"Lechubestia sañosa", "Lechubestia primitiva", "Lechubestia salvaje", "Hipogrifo Plumavieja", "Alacervo Plumavieja", "Tormento Rozapluma", "Patriarca Rozapluma", "Antilus el Surcador"}, {"Lechubestia sañosa", "Lechubestia primitiva", "Lechubestia salvaje", "Hipogrifo Plumavieja", "Alacervo Plumavieja", "Tormento Rozapluma", "Patriarca Rozapluma", "Antilus el Surcador"}}},
    [3129] = {n="Armas del espíritu", d="El médico brujo Uzer'i quiere que esperes mientras prepara las armas."},
    [3161] = {n="Gahz'rilo", d="Marvon Buscarroblones de Tanaris quiere que reúnas 30 adornos de gahz'rilo.", objs={"Gahz'ridian"}},
    [3221] = {n="Habla con Renferrel", d="Habla con el boticario Renferrel en El Sepulcro."},
    [3261] = {n="Jorn Visioceleste", d="Habla con Jorn Visioceleste en el Campamento Taurajo."},
    [3281] = {n="La plata robada", d="Llévale la plata robada a Gazrog en El Cruce.", objs={"Plata robada"}},
    [3301] = {n="Mura Runatótem", d="Habla con Mura Runatótem en El Sepulcro."},
    [3341] = {n="Acaba con la amenaza", d="Andrew Brownell quiere que mates a Amnennar el Gélido y que le lleves su calavera.", tgo={{"Amnennar el Gélido"}}},
    [3362] = {n="El Valle Cardizal", d="Tran'rek de Gadgetzan quiere que mates a 8 cardizales nudosos y a 8 enraizadores cardizales.", tgo={{"Cardizal nudoso"}, {"Enraizador Cardizal"}}},
    [3369] = {n="En las pesadillas", d="Lleva el Fragmento de Pesadilla a Hamuul Runatótem en el Alto de los Ancestros."},
    [3373] = {n="La esencia de Eranikus", d="Coloca la esencia de Eranikus en la fuente de esencia situada en su guarida del Templo Sumergido."},
    [3376] = {n="La cabeza de Cornapunta", d="Lleva la cabeza del Jefe Cornapunta Mantospina a Valiente Ventopluma a Mesa de la Nube Roja.", tgo={{"Jefe Cornapunta Mantospina"}}},
    [3380] = {n="El Templo Sumergido", d="Encuentra a Marvon Buscarroblones en Tanaris."},
    [3441] = {n="Castigo divino", d="Escucha a Kalaran Espada del Viento.", tgo={{"Kalaran Espada del Viento"}}},
    [3442] = {n="La llama pura", d="Lleva 4 corazones de llama y 4 globos de aceite gólem a Kalaran Espada del Viento.", tgo={{"Elemental llameante", "Elemental inferno", "Elemental de magma"}, {"Golen de guerra templado", "Gólem de guerra pesado", "Elemental de magma"}}},
    [3443] = {n="Forjar el mango", d="Lleva 8 dagas chapadas en torio a Kalaran Espada del Viento.", tgo={{"Geólogo Hierro Negro", "Vapoherrero Hierro Negro", "Trabajador esclavo", "Esclavista Hierro Negro", "Capataz Hierro Negro", "Acerador Hierro Negro", "Argos Hierro Negro", "Vigía Hierro Negro"}}},
    [3444] = {n="El Círculo de Piedras", d="Recupera el Círculo de Piedras del taller de Marvon Buscarroblones, en Trinquete.", objs={"Cofre de Marvon"}},
    [3446] = {n="En las profundidades", d="Encuentra el Altar de Hakkar en el Templo Sumergido, en el Pantano de las Penas."},
    [3447] = {n="El secreto del círculo", d="Ve al Templo Sumergido y descubre el secreto oculto en el círculo de estatuas."},
    [3452] = {n="El soporte para la llama", d="Lleva un Símbolo de Ragnaros a Kalaran Espada del Viento.", tgo={{"Chamán Oscuro Crepuscular", "Guardia de Fuego Crepuscular", "Geomántico Crepuscular", "Idólatra Crepuscular"}}},
    [3453] = {n="La Antorcha de Reprensión", d="Espera a que Kalaran Espada del Viento termine la Antorcha de Reprensión.", tgo={{"Kalaran Espada del Viento"}}},
    [3454] = {n="La Antorcha de Reprensión", d="Coge la Antorcha de Reprensión."},
    [3462] = {n="Escudero Maltrake", d="Habla con mi enviado, el escudero Maltrake."},
    [3463] = {n="¡Préndelas fuego!", d="Entra en las 4 torres del centinela e incéndialas con la Antorcha de Reprensión.", objs={"Blandón de centinela"}},
    [3481] = {n="Abalarios...", d="Abre el cofre."},
    [3501] = {n="Todo cuenta en grandes cantidades", d="Llévale a Kum'isha fragmentos de draenetista imperfecta y te recompensará por cada fragmento entregado.", tgo={{"Ogro Fauzatroz", "Mago ogro Fauzatroz", "Tosco Fauzatroz", "Destructor Fauzatroz", "Brujo Machacamiedo", "Perdido desdichado", "Buscador de portales", "Destripador negro"}}},
    [3504] = {n="Traición", d="Entrega la carta sellada a Ag'tor Puñosangre en Azshara."},
    [3505] = {n="Traición", d="Mata a 10 reivindicadores y 10 agrimensores elfos de sangre antes de buscar el campamento de Magus Rimtori. Una vez allí, busca algo que sea importante para ella, algo con lo que provocar un combate.", tgo={{"Reivindicador elfo de sangre"}, {"Perito elfo de sangre"}}},
    [3517] = {n="El robo de conocimientos", d="Encuentra la tablilla de Beth'Amara, la tablilla de Jin'yael, la tablilla de Markri y la tablilla de Sael'hai antes de volver junto a Jediga en Azshara.", objs={"Tablilla de Beth'Amara", "Tablilla de Jin'yael", "Tablilla de Markri", "Tablilla de Sael'hai"}},
    [3518] = {n="Entrega a Magatha", d="Llévale la tablilla de Beth'Amara a Magatha en Cima del Trueno."},
    [3520] = {n="Los espíritus de los estriadores", d="Captura el espíritu de 3 estridadores en Feralas y después ve a ver a Yeh'kinya al Puerto Bonvapor.", tgo={{"Espíritu estridador"}}},
    [3523] = {n="La plaga de la Zahúrda", d="Si decides ayudar a Belnistrasz, habla con él otra vez y devuélvele la piedra de juramento."},
    [3525] = {n="Extinguir el ídolo", d="Acompaña a Belnistrasz al ídolo jabaespín en Zahúrda Rajacieno.\nProtégelo mientras realiza el ritual para inutilizar el ídolo."},
    [3527] = {n="La profecía de Mosh'aru", d="Llévale la primera y segunda tablillas de Mosh'aru a Yeh'kinya, que está en Tanaris.", tgo={{"Theka el Mártir", "Theka el Mártir Cambiaforma"}, {"Hidromántica Velratha"}}},
    [3528] = {n="El dios Hakkar", d="Llévale el huevo de Hakkar relleno a Yeh'kinya, que está en Tanaris."},
    [3541] = {n="Entrega a Jes'rimon", d="Envía la tablilla de Jin'yael a Jes'rimon en Orgrimmar."},
    [3542] = {n="Entrega a Andron Gant", d="Llévale la tablilla de Markri a Andron Gant en Entrañas."},
    [3601] = {n="¡Kim'jael, claro!", d="Busca en el campamento base thalassiano la brújula de Kim'jael, el telescopio, el pollo relleno y el y llévaselo todo a Azshara.", objs={"Equipo de Kim'jael"}},
    [3631] = {n="Invoca un malignoecus", d="Habla con Strahad Farsan en Los Baldíos."},
    [3783] = {n="Yeti... ¿ya hemos llegado?", d="Reúne 10 pieles gruesas de yeti para Umi Risitas en Vista Eterna.", tgo={{"Cardo Nevado huido", "Yeti Cardo Nevado"}}},
    [3801] = {n="El legado de los Hierro Negro", d="Habla con Franclorn Forjafina si te interesa obtener una llave de la ciudad."},
    [3802] = {n="El legado de los Hierro Negro", d="Mata a Finoso Virunegro y recupera el gran martillo, Ferrovil. Lleva a Ferrovil al Santuario de Thaurissan y coloca el martillo en la estatua de Franclorn Forjador.|n", tgo={{"Finoso Virunegro"}}},
    [3821] = {n="Roca Machacamiedo", d="Adéntrate en Las Estepas Ardientes y averigua qué le ha ocurrido a Sha'ni Colminilludo."},
    [3822] = {n="Krom'Grul", d="Recupera la alianza de la nariz de Sha'ni de Krom'Grul y llévasela a Thal'trak en Kargath. Busca por las diferentes cuevas y minas de la Roca Machacamiedo.", tgo={{"Krom'Grul"}}},
    [3844] = {n="Un secreto bien guardado", d="Busca alrededor del estanque alguna pista sobre a quién perteneció la balsa destrozada."},
    [3845] = {n="Un secreto bien guardado", d="Examina los objetos de la talega y devuélveselos a su propietario."},
    [3881] = {n="Expedición Salvación", d="Lleva un cajón de comestibles y el equipo de investigación a Williden Marshal en el Cráter de Un'Goro.", objs={"Cajón de comestibles", "Equipo de investigación"}},
    [3882] = {n="Choca esos huesos", d="Lleva 8 huesos de dinosaurio a Chispik Nilminer en el Cráter de Un'Goro.", tgo={{"Stegodon", "Estegodón escamado", "Estegodón de púas", "Estegodón Tronavapuleus", "Diemetradón joven", "Diemetradón", "Diemetradón viejo"}}},
    [3884] = {n="Diario de Williden", d="Devuelve el diario a Williden Marshal en algún lugar del Cráter de Un'Goro."},
    [3901] = {n="Sacudir esqueletos", d="Mata a 12 esqueletos armadóseos y cuando lo hayas hecho, vuelve a buscar al sacerdote de las Sombras Sarvis a Camposanto.", tgo={{"Esqueleto armadóseo"}}},
    [3902] = {n="Hurgar en Camposanto", d="Busca 6 piezas de mercancías extraviadas por Camposanto y los alrededores y llévaselas al guardia de la muerte Saltain.", objs={"Cajas de equipamiento"}},
    [3906] = {n="La discordia de las llamas", d="Ve a la cantera de la Montaña Roca Negra y ejecuta al gran maestro Pyron. Vuelve junto a Truenozón cuando hayas completado este encargo.", tgo={{"Maestro Supremo Pyron"}}},
    [3907] = {n="La discordia de las llamas", d="Adéntrate en las Profundidades de Roca Negra y localiza a Lord Incendius. Mátalo y llévale toda la información que encuentres a Truenozón.", tgo={{"Lord Incendius"}, {"Lord Incendius"}}},
    [3908] = {n="Un secreto bien guardado", d="Lleva la Espada de Linken a Donova Cubilnevado en Cuna del Invierno."},
    [3909] = {n="El Elixir de Videre", d="Busca a Gregan Vomitabrebaje en el norte de Feralas. Con él, aprende cómo puedes obtener el Elixir de Videre. Cuando lo sepas, vuelve con Donova Cubilnevado en Cuna del Invierno.", tgo={{"Gregan Vomitabrebaje"}}},
    [3912] = {n="Encuentro en la tumba", d="Ve al cementerio a las afueras de Gadgetzan y utiliza el Elixir de Videre. Sigue las demás instrucciones de Donova para encontrar a Gaeriyan."},
    [3913] = {n="Una situación mortal", d="Resucita y busca la lápida de la que te habló Gaeriyan."},
    [3914] = {n="La Espada de Linken", d="Entrega la Espada superior a Linken en el Cráter de Un'Goro."},
    [3941] = {n="La ayuda de una gnoma", d="Encuentra a J.D. Collie en la cueva del Refugio de Marshal."},
    [3942] = {n="Recuerdos de Linken", d="Encuentra a Eridan Vientoazul en el sur de Frondavil."},
    [4021] = {n="¡Contraataca!", d="Llévale una pieza del estandarte de Krom'zar a Regthar Portamorta, al oeste de El Cruce.", objs={"Estandarte de Krom'zar"}},
    [4061] = {n="La revuelta de las máquinas", d="Adéntrate en Las Estepas Ardientes y recupera 10 fragmentos de elemental agrietado para Hierofante Theodora Mulvadania.\nRecuerdas que Theodora mencionó que los golems y elementales de esa región eran la fuente de estos fragmentos.", tgo={{"Elemental obsidiano superior", "Atracador de guerra", "Atracador estropeado"}}},
    [4062] = {n="La revuelta de las máquinas", d="Lleva el ejemplar de fragmento de Elemental a Lotwil Veriatus.\nRecuerdas que Theodora dijo que Lotwil se encontraba en un campamento hacia el este."},
    [4081] = {n="MATAR INMEDIATAMENTE: enanos Hierro Negro", d="Adéntrate en las Profundidades de Roca Negra ¡y destruye a esos viles agresores!\nEl señor de la guerra Dientegore quiere que mates a 15 custodios de Yunque Colérico, 10 alcaides de Yunque Colérico y 5 lacayos de Yunque Colérico. Vuelve junto a él cuando hayas acabado la tarea.", tgo={{"Custodio Yunque Colérico"}, {"Alcaide de Yunque Colérico"}, {"Lacayo Yunque Colérico"}}},
    [4084] = {n="Corazón de plata", d="Recoge 11 zarpas plateadas y 1 corazón de Troncoferro para Eridan Vientoazul de Frondavil.", tgo={{"Oso Zarpira", "Pardo Zarpira", "Aplastador Zarpira", "Lobo Zarpayel", "Carroñero Zarpayel", "Devastador Zarpayel", "Aullador de la Muerte", "Mongress"}, {"Errante Troncoferro", "Vapuleador Troncoferro"}}},
    [4102] = {n="Limpiar Frondavil", d="Lleva 15 unidades de sangre ámbar a Maybess Brisafluvial a Frondavil.", tgo={{"Arrancamusgo Alabeo", "Machacador Alabeo", "Dessecus"}}},
