    [4123] = {n="El Corazón de la Montaña", d="Llévale el Corazón de la Montaña a Maxwort Suprandor en Las Estepas Ardientes.", objs={"El corazón de la montaña"}},
    [4134] = {n="La receta perdida de Cebatruenos", d="Llévale la receta perdida de Cebatruenos a Vivian Latumba en Kargath.", tgo={{"Hurley Negrálito", "Compinche Negrálito"}}},
    [4136] = {n="Ribbly Llavenrosca", d="Llévale la cabeza de Ribbly a Yuka Llavenrosca en Las Estepas Ardientes.", tgo={{"Ribbly Llavenrosca"}}},
    [4145] = {n="Larion y Muigin", d="Caza 5 latigadores Pétalo de Sangre, 5 trilladores Pétalo de Sangre, 5 desolladores Pétalo de Sangre y 5 tramperos Pétalo de Sangre para Larion en el Refugio de Marshal.", tgo={{"Azotador Sangrepétalo"}, {"Trampero Sangrepétalo"}, {"Despellejador Sangrepétalo"}, {"Trillador Sangrepétalo"}}},
    [4147] = {n="El taller de Marvon", d="Viaja hasta el taller de Marvon Buscarroblones en Trinquete."},
